<?php
namespace App\Services\Viva;
use App\Models\VivaCandidateMapping;use App\Models\VivaImportBatch;use Carbon\Carbon;use Illuminate\Support\Facades\DB;use Throwable;
final class VivaBoardValidationService{
 public function __construct(private VivaRuleConfig$rules){}
 public function validate(int$id):VivaImportBatch{$b=VivaImportBatch::query()->where('import_type','board')->findOrFail($id);$b->update(['status'=>'validating','failure_message'=>null,'progress_percent'=>0]);try{$duplicateCodes=DB::connection('exam')->table('viva_board_import_staging')->where('batch_id',$id)->whereNotNull('code')->groupBy('code')->havingRaw('COUNT(*) > 1')->pluck('code')->flip();$total=max(1,(int)$b->staged_rows);$done=$valid=$warn=$invalid=0;$chunk=max(500,(int)config('viva.board_validation_chunk_size',3000));DB::connection('exam')->table('viva_board_import_staging')->where('batch_id',$id)->orderBy('id')->chunkById($chunk,function($rows)use($b,$duplicateCodes,$total,&$done,&$valid,&$warn,&$invalid){$codes=$rows->pluck('code')->filter()->unique()->values();$maps=VivaCandidateMapping::query()->whereIn('code',$codes)->get()->keyBy('code');foreach($rows as$r){$errors=[];$warnings=[];$map=$r->code?$maps->get($r->code):null;if(!$r->code)$errors[]='CODE is required.';elseif($duplicateCodes->has($r->code))$errors[]='CODE appears more than once in this Board data file.';elseif(!$map)$errors[]='CODE does not exist in the approved Viva Candidate Mapping.';$date=$this->date($r->raw_viva_date);if(!$r->raw_viva_date)$errors[]='VIVA_DATE is required.';elseif(!$date)$errors[]='VIVA_DATE must be a valid DDMMYY date.';if(trim((string)($r->member_id??''))==='')$errors[]='MEMBER_ID is required.';$markRaw=strtoupper(trim((string)($r->raw_mark??'')));$mark=null;$attendance=null;if($markRaw==='')$errors[]='MARK is required and must be a valid number or ABS.';elseif($markRaw==='ABS')$attendance='absent';elseif(!is_numeric($markRaw))$errors[]='MARK must be a valid number or ABS.';else{$mark=(float)$markRaw;$attendance='appeared';if($mark<0)$errors[]='MARK cannot be negative.';if($mark>$this->rules->fullMark())$errors[]='MARK exceeds the configured Viva full mark of '.number_format($this->rules->fullMark(),2).'.';}if($r->invalid_flag)$warnings[]='Source INVALID flag is marked for Commission review.';if($r->issue_flag)$warnings[]='Source ISSUE flag is marked for Commission review.';$status=$errors?'invalid':($warnings?'warning':'valid');if($status==='invalid')$invalid++;elseif($status==='warning')$warn++;else$valid++;DB::connection('exam')->table('viva_board_import_staging')->where('id',$r->id)->update(['viva_candidate_mapping_id'=>$map?->id,'registration_id'=>$map?->registration_id,'viva_date'=>$date?->format('Y-m-d'),'mark'=>$mark,'attendance_status'=>$attendance,'validation_status'=>$status,'validation_errors'=>$errors?json_encode($errors):null,'validation_warnings'=>$warnings?json_encode($warnings):null,'updated_at'=>now()]);$done++;} $b->update(['processed_rows'=>$done,'valid_rows'=>$valid,'warning_rows'=>$warn,'invalid_rows'=>$invalid,'progress_percent'=>min(99.9,round($done/$total*100,4))]);});$b->update(['status'=>'validated','processed_rows'=>$done,'valid_rows'=>$valid,'warning_rows'=>$warn,'invalid_rows'=>$invalid,'identity_conflict_rows'=>0,'progress_percent'=>100,'validated_at'=>now(),'finished_at'=>now()]);return$b->refresh();}catch(Throwable$e){$b->update(['status'=>'failed','failure_message'=>mb_substr($e->getMessage(),0,65000),'finished_at'=>now()]);throw$e;}}
 private function date($v):?Carbon{$s=trim((string)($v??''));if(!preg_match('/^\d{6}$/',$s))return null;try{$d=Carbon::createFromFormat('!dmy',$s);return$d&&$d->format('dmy')===$s?$d:null;}catch(Throwable){return null;}}
}
